#!/usr/bin/env python3
"""Offline installer for SIRAJ d.16 + d.17.

Run from ~/frappe-bench/apps/siraj_research. It extracts only changed
runtime/docs files from an embedded base64 tarball; no network is used.
"""
import base64
import io
import pathlib
import sys
import tarfile

DATA = """"""

def main() -> None:
    root = pathlib.Path.cwd()
    if not (root / "siraj_research" / "hooks.py").is_file():
        sys.exit("Run this from ~/frappe-bench/apps/siraj_research")
    payload = base64.b64decode("".join(DATA.split()))
    with tarfile.open(fileobj=io.BytesIO(payload), mode="r:gz") as archive:
        members = archive.getnames()
        if any(name.startswith("/") or ".." in pathlib.PurePosixPath(name).parts
               for name in members):
            sys.exit("Unsafe archive member")
        archive.extractall(root)
    print("Extracted", len(members), "files (d.16 + d.17).")
    print("Next: bench --site frappe.com build --app siraj_research")
    print("Then: bench --site frappe.com execute siraj_research.api.geo_package.export_offline_package")

if __name__ == "__main__":
    main()
